function [x] = command_value(w, full, s)
%COMMAND_VALUE  A command word (a rotor's torque, a gimbal's rate) as a value of its full scale.
%   w: int (passed a whole number)
%   full: real[1] (passed a plain number)
%   s: EmuScale (passed rec)
%   returns x: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    x = 0;
    x = ((w / s.word) * full);
end
